// ❌ Anemic: rules scattered; invariants unenforceable.
public class Order {
    public int Id { get; set; }
    public decimal Total { get; set; }
    public string Status { get; set; } = "New";   // any string, any setter
}

public class OrderService {
    public void Ship(int orderId) {
        var o = _db.Orders.Find(orderId);
        if (o.Status == "Paid") o.Status = "Shipped";   // rule #1 lives here
    }
}
public class ReportService {
    public void Refund(int orderId) {
        var o = _db.Orders.Find(orderId);
        if (o.Status != "Delivered") o.Status = "Refunded"; // rule #2 reimplemented
    }
}
