// ✅ Rich: the object protects its own state.
public class Order {
    public int Id { get; private set; }
    public decimal Total { get; private set; }
    public OrderStatus Status { get; private set; } = OrderStatus.New;

    public void MarkPaid(string paymentRef) {
        if (Status != OrderStatus.New)
            throw new InvalidOperationException($"Cannot pay order in {Status}");
        Status = OrderStatus.Paid;
    }

    public void Ship() {
        if (Status != OrderStatus.Paid)
            throw new InvalidOperationException("Cannot ship an unpaid order");
        Status = OrderStatus.Shipped;
    }
}
// One place per rule; illegal transitions throw; services just orchestrate.
